import {updateBoard} from './board-dom.js';
const names={p:'pedone',n:'cavallo',b:'alfiere',r:'torre',q:'donna',k:'re'};
import {animateBoard} from './motion.js';
export function drawBoard(host,chess,{flipped=false,selected=null,disabled=false,last=null,draw=null}={}){const legal=selected?chess.moves({square:selected,verbose:true}).map(m=>m.to):[];const html=Array.from({length:64},(_,i)=>{const row=Math.floor(i/8),col=i%8,f=flipped?7-col:col,r=flipped?row:7-row,sq='abcdefgh'[f]+(r+1),p=chess.get(sq);return `<button class="square ${(f+r)%2===0?'dark':''} ${sq===selected?'selected':''} ${legal.includes(sq)?'legal':''} ${last&&(last.from===sq||last.to===sq)?'last':''}" data-sq="${sq}" aria-label="${sq}${p?' '+(p.color==='w'?'Bianco ':'Nero ')+names[p.type]:''}" ${disabled?'disabled':''}>${p?`<img src="pieces/${p.color}${p.type.toUpperCase()}.png" alt="" draggable="false">`:''}${col===0?`<span class="coord rank">${r+1}</span>`:''}${row===7?`<span class="coord">${'abcdefgh'[f]}</span>`:''}</button>`}).join('');updateBoard(host,html);animateBoard(host,chess.fen(),flipped,{draw:draw??chess.isDraw()})}
export function choosePiece(color){return new Promise(resolve=>{const d=document.createElement('dialog');d.innerHTML='<h2>Scegli la promozione</h2><div class="promotion-choices">'+['q','r','b','n'].map(p=>`<button data-piece="${p}" aria-label="${names[p]}"><img src="pieces/${color}${p.toUpperCase()}.png" alt="${names[p]}"></button>`).join('')+'</div><button data-piece="">Annulla</button>';document.body.append(d);const done=p=>{d.close();d.remove();resolve(p)};d.onclick=e=>{const b=e.target.closest('[data-piece]');if(b)done(b.dataset.piece)};d.oncancel=e=>{e.preventDefault();done(null)};d.showModal()})}
